#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Tools;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    public abstract class PrismaticPylonProjectileMode
    {
        public abstract NamespaceID GetModeBuffID();
        public virtual Vector3 GetHSV(Entity entity, Entity oldProjectile) => Vector3.zero;
        public virtual Color GetLightColor(Entity entity, Entity oldProjectile) => Color.red;
        public virtual void Apply(Entity entity, NamespaceID projectileID, Entity oldProjectile, Vector3 position, Vector3 velocity)
        {
            ReplaceProjectile(entity, projectileID, oldProjectile, position, velocity);
        }
        public virtual void ApplyToLight(Entity prism, List<Entity> projectiles)
        {
            foreach (var projectile in projectiles)
            {
                projectile.AddBuff(GetModeBuffID())?.Let(b => ApplyToBuff(prism, projectile, b));
            }
        }
        public virtual void ApplyToBuff(Entity entity, Entity oldProjectile, Buff buff)
        {

        }
        #region ����
        public static SpawnParams GetSpawnParams(Entity? prism, Entity oldProjectile, Vector3 velocity, Vector3 hsv, Color lightColor)
        {
            var spawnParams = new SpawnParams();
            spawnParams.SetProperty(EngineEntityProps.FACTION, oldProjectile.GetFaction());
            spawnParams.SetProperty(VanillaEntityProps.DAMAGE, oldProjectile.GetDamage());
            spawnParams.SetProperty(LogicEntityProps.HSV_OFFSET, hsv);
            spawnParams.SetProperty(LogicEntityProps.LIGHT_COLOR, lightColor);
            if (prism != null)
            {
                spawnParams.SetProperty(PrismaticPylon.PROP_TRANSFORMER_PRISM, new EntityID(prism));
            }
            spawnParams.EntityVelocity = velocity;
            return spawnParams;
        }
        public static Entity? SpawnProjectile(NamespaceID projectileID, Vector3 pos, Entity oldProjectile, SpawnParams spawnParams)
        {
            return oldProjectile.Level.SpawnSourced(projectileID, pos, oldProjectile.SpawnerReference, spawnParams);
        }
        #endregion

        #region ����
        public static SpawnParams GetCreateProjectileSpawnParams(Entity? prism, Entity oldProjectile, Vector3 velocity, Vector3 hsv, Color lightColor)
        {
            var spawnParams = GetSpawnParams(prism, oldProjectile, velocity, hsv, lightColor);
            return spawnParams;
        }
        public static Entity? CreateProjectile(Entity? prism, NamespaceID projectileID, Entity oldProjectile, Vector3 position, Vector3 velocity, Vector3 hsv, Color lightColor)
        {
            var spawnParams = GetCreateProjectileSpawnParams(prism, oldProjectile, velocity, hsv, lightColor);
            return CreateProjectile(prism, projectileID, oldProjectile, position, spawnParams);
        }
        public static Entity? CreateProjectile(Entity? prism, NamespaceID projectileID, Entity oldProjectile, Vector3 position, SpawnParams spawnParams)
        {
            var newProjectile = SpawnProjectile(projectileID, position, oldProjectile, spawnParams)?.Let(proj =>
            {
                var collider = prism?.GetMainCollider();
                if (collider != null)
                {
                    proj.AddIgnoredProjectileCollider(collider);
                }
            });
            return newProjectile;
        }
        #endregion

        #region �滻
        protected SpawnParams GetReplaceProjectileSpawnParams(Entity prism, Entity oldProjectile, Vector3 velocity)
        {
            return GetSpawnParams(prism, oldProjectile, velocity, GetHSV(prism, oldProjectile), GetLightColor(prism, oldProjectile));
        }
        protected Entity? ReplaceProjectile(Entity entity, NamespaceID projectileID, Entity oldProjectile, Vector3 position, Vector3 velocity)
        {
            var spawnParams = GetReplaceProjectileSpawnParams(entity, oldProjectile, velocity);
            return ReplaceProjectile(entity, projectileID, oldProjectile, position, spawnParams);
        }
        protected Entity? ReplaceProjectile(Entity prism, NamespaceID projectileID, Entity oldProjectile, Vector3 position, SpawnParams spawnParams)
        {
            var newProjectile = CreateProjectile(prism, projectileID, oldProjectile, position, spawnParams)?.Let(proj =>
            {
                proj.AddBuff(GetModeBuffID())?.Let(b => ApplyToBuff(prism, oldProjectile, b));
            });
            return newProjectile;
        }
        #endregion

        #region 
        public static SpawnParams GetCloneProjectileSpawnParams(Entity? prism, Entity oldProjectile, Vector3 velocity)
        {
            return GetSpawnParams(prism, oldProjectile, velocity, oldProjectile.GetHSVOffset(), oldProjectile.GetLightColor());
        }
        public static Entity? CloneProjectile(Entity? prism, NamespaceID projectileID, Entity oldProjectile, Vector3 position, Vector3 velocity)
        {
            var spawnParams = GetCloneProjectileSpawnParams(prism, oldProjectile, velocity);
            return CloneProjectile(prism, projectileID, oldProjectile, position, spawnParams);
        }
        public static Entity? CloneProjectile(Entity? prism, NamespaceID projectileID, Entity oldProjectile, Vector3 position, SpawnParams spawnParams)
        {
            var newProjectile = CreateProjectile(prism, projectileID, oldProjectile, position, spawnParams)?.Let(proj =>
            {
                CopyPrismaticPylonBuffs(proj, oldProjectile);
            });
            return newProjectile;
        }
        public static void CopyPrismaticPylonBuffs(Entity to, Entity from)
        {
            foreach (var mode in PrismaticPylon.projectileModes)
            {
                var buffID = mode.GetModeBuffID();
                if (!to.HasBuff(buffID))
                {
                    var buff = from.GetFirstBuff(buffID);
                    if (buff != null)
                    {
                        var newBuff = buff.Clone(to);
                        to.AddBuff(newBuff);
                    }
                }
            }
        }
        #endregion ����
    }
}
